import{_ as t,o,c as s,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const a="/rakkii-cars-guide/screenshots/03-staff-self-service-me-hub/01-request-leave.png",n="/rakkii-cars-guide/screenshots/03-staff-self-service-me-hub/02-my-profile-scorecards.png",m=JSON.parse('{"title":"3. Staff self-service: the Me hub","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/03-staff-self-service-me-hub.md","filePath":"chapters/03-staff-self-service-me-hub.md","lastUpdated":1793268728000}'),i={name:"chapters/03-staff-self-service-me-hub.md"};function l(d,e,c,p,h,g){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-staff-self-service-the-me-hub" tabindex="-1">3. Staff self-service: the Me hub <a class="header-anchor" href="#_3-staff-self-service-the-me-hub" aria-label="Permalink to &quot;3. Staff self-service: the Me hub&quot;">​</a></h1><p><strong>For:</strong> Lead Technician, Sales Agent (and any staff with a login) · <strong>Hub:</strong> Me (<code>/me</code>)</p><p>The <strong>Me</strong> hub is your personal corner of the app. Everything here is about you only: your punches, your overtime, your leave, your payslips and your record. Nobody else&#39;s data shows here.</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>What it is for</th></tr></thead><tbody><tr><td>Time clock</td><td><code>/me/clock</code></td><td>Clock in and out, see today&#39;s punches</td></tr><tr><td>My payslip</td><td><code>/me/payslip</code></td><td>Payslips from locked payroll periods</td></tr><tr><td>Leave</td><td><code>/me/leave</code></td><td>Request vacation, sick, unpaid, SIL and half days</td></tr><tr><td>My overtime</td><td><code>/me/overtime</code></td><td>File overtime and see its status</td></tr><tr><td>My commission</td><td><code>/me/commission</code></td><td>Only if you have commission lines (see <a href="/rakkii-cars-guide/chapters/04-sales-agent-guide">Chapter 4</a>)</td></tr><tr><td>My incentive</td><td><code>/me/incentive</code></td><td>Sales agents with a quarterly target</td></tr><tr><td>My profile</td><td><code>/me/profile</code></td><td>Your employee record, documents and finalized scorecards</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Owners</p><p>The owner does not clock in, file personal leave or overtime. Opening those pages as owner shows &quot;This page is for staff.&quot; The owner&#39;s Me hub keeps <strong>My payslip</strong> and <strong>My profile</strong>.</p></div><h2 id="_3-1-time-clock-me-clock" tabindex="-1">3.1 Time clock (<code>/me/clock</code>) <a class="header-anchor" href="#_3-1-time-clock-me-clock" aria-label="Permalink to &quot;3.1 Time clock (`/me/clock`)&quot;">​</a></h2><ol><li>Open <strong>Me › Time clock</strong>.</li><li>Take the photo if the shop requires one.</li><li>Press <strong>Clock in</strong> (or <strong>Clock out</strong>).</li><li>Check the row under <strong>Today</strong>: time in, time out (or &quot;still in&quot;), shop, and status.</li></ol><h3 id="off-site-punches" tabindex="-1">Off-site punches <a class="header-anchor" href="#off-site-punches" aria-label="Permalink to &quot;Off-site punches&quot;">​</a></h3><p>The app compares your location with the shop&#39;s map pin and allowed radius.</p><ul><li><strong>Inside the radius:</strong> the punch is saved as normal.</li><li><strong>Outside the radius:</strong> you see a warning. Type a <strong>Reason</strong> (&quot;A reason is required for an off-site punch&quot;) such as &quot;Road test along Roosevelt Ave&quot; or &quot;Picking up bumper from supplier&quot;, then punch.</li></ul><p>An off-site punch is <strong>Pending</strong> until the owner approves or rejects it in <strong>HR › Attendance</strong>. Pending or rejected off-site time is left out of payroll, so give a clear reason.</p><div class="tip custom-block"><p class="custom-block-title">Forgot to clock out?</p><p>Tell the owner. They can close the open punch with the real time and a reason. Open punches are listed on the payroll screen and are not paid until closed.</p></div><h2 id="_3-2-filing-overtime-me-overtime" tabindex="-1">3.2 Filing overtime (<code>/me/overtime</code>) <a class="header-anchor" href="#_3-2-filing-overtime-me-overtime" aria-label="Permalink to &quot;3.2 Filing overtime (`/me/overtime`)&quot;">​</a></h2><p>Overtime is paid only after it is approved, and never for more hours than you actually punched.</p><ol><li>Open <strong>Me › My overtime</strong>.</li><li>Press <strong>Request OT</strong>.</li><li>Enter the <strong>Date</strong>, <strong>Hours</strong> and a <strong>Reason</strong> (for example &quot;Finished paint booth for promised release&quot;).</li><li>Press <strong>File request</strong>.</li></ol><p>The page opens on <strong>My week</strong> (Monday to Sunday) with your punches for the week. Your requests appear under <strong>My overtime</strong> with their <strong>Source</strong>, <strong>Hours</strong> and <strong>Status</strong> (Pending, Approved, Rejected). Time past your shift end can also appear automatically for approval. The owner may approve fewer hours than you claimed and add a note.</p><h2 id="_3-3-requesting-leave-me-leave" tabindex="-1">3.3 Requesting leave (<code>/me/leave</code>) <a class="header-anchor" href="#_3-3-requesting-leave-me-leave" aria-label="Permalink to &quot;3.3 Requesting leave (`/me/leave`)&quot;">​</a></h2><p>The top of the page shows your balances for the year: <strong>Vacation remaining</strong>, <strong>Sick remaining</strong>, <strong>Unpaid taken</strong> and <strong>SIL remaining</strong>. Pending days stay on the balance until a decision is made.</p><ol><li>Press <strong>Request leave</strong>.</li><li>Choose the <strong>Type</strong>: Vacation, Sick, Unpaid, or Service incentive (SIL).</li><li>Pick the <strong>Start date</strong> and <strong>End date</strong>.</li><li>For a half day, set <strong>Half day</strong> to <strong>Morning (AM)</strong> or <strong>Afternoon (PM)</strong> (one date only). Otherwise leave it at <strong>Full day</strong>.</li><li>Add a <strong>Note</strong> if useful, then press <strong>Request</strong>.</li></ol><p>Your request is listed under <strong>My requests</strong> with its dates (for example &quot;Nov 10, 2026&quot;), type, days and status, and the balance tiles show it as <strong>Pending</strong>. You can <strong>Cancel</strong> a request that has not been decided. When the owner approves it, the status changes to <strong>approved</strong> and the days come off <strong>Vacation remaining</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Open jobs and leave</p><p>If you have open assigned jobs, the owner sees them when approving your leave and can move them to another technician. Tell the desk about cars that are due during your leave.</p></div><p><img src="'+a+'" alt="Request leave dialog with Type, dates and Half day"></p><h2 id="_3-4-viewing-payslips-me-payslip" tabindex="-1">3.4 Viewing payslips (<code>/me/payslip</code>) <a class="header-anchor" href="#_3-4-viewing-payslips-me-payslip" aria-label="Permalink to &quot;3.4 Viewing payslips (`/me/payslip`)&quot;">​</a></h2><p>Payslips appear only after the owner <strong>locks</strong> the payroll period (&quot;No payslips yet. They appear here once payroll is locked.&quot;).</p><ol><li>Open <strong>Me › My payslip</strong>.</li><li>Pick a <strong>Period</strong> from the list (shows <strong>Gross</strong> and <strong>Net</strong>).</li><li>Read the breakdown: pay basis and rate, <strong>Regular hours</strong>, <strong>OT hours</strong>, <strong>OT pay</strong>, <strong>Days paid</strong>, premiums and allowances, then deductions (<strong>SSS</strong>, <strong>PhilHealth</strong>, <strong>Pag-IBIG</strong>, <strong>Withholding</strong>, <strong>Other</strong>, loan instalments), <strong>Total deductions</strong> and <strong>Net</strong>.</li><li>Press <strong>Print</strong> for a paper or PDF copy.</li></ol><p>The payslip shows when the period was locked and by whom. Payment itself happens outside the app (cash or bank).</p><h2 id="_3-5-my-profile-me-profile" tabindex="-1">3.5 My profile (<code>/me/profile</code>) <a class="header-anchor" href="#_3-5-my-profile-me-profile" aria-label="Permalink to &quot;3.5 My profile (`/me/profile`)&quot;">​</a></h2><p>Your own employee record, read-only.</p><ul><li><strong>Overview</strong> — identity, role, position, department, hire date, rest day, government numbers (TIN, SSS, PhilHealth, Pag-IBIG), contact and emergency contact. If something is wrong, ask the owner to fix it in <strong>HR › Directory</strong>.</li><li><strong>Documents</strong> — employment documents the shop has on file for you (contract, job offer, ID, COE request, letters). Press <strong>Download</strong> to get a copy.</li><li><strong>Leave</strong> — your balances and this year&#39;s requests.</li><li><strong>Scorecards</strong> — your KPI scorecards <strong>once they are finalized</strong>. Draft scorecards stay hidden until the owner presses <strong>Finalise</strong>. Each card shows the period, each KPI score with its rating and comment, and the overall result.</li></ul><p><img src="'+n+'" alt="My profile, Scorecards section with a finalized card"></p>',30)])])}const f=t(i,[["render",l]]);export{m as __pageData,f as default};
